// Sylo redesign prototypes: static HTML (one file per page), shared sylo.css.
import fs from "node:fs";
const NAV = [
  ["", [["console", "Console", "brass"]]],
  ["", [["accounts", "Accounts", "brass", "", [["entity", "Entity", "38", "brass"], ["local", "Local accounts", "124", "patina"], ["kyc", "KYC", "17", "copper"], ["game", "Game accounts", "9", "slate"], ["enrollment", "Enrollment", "14", "slate"]], "entity.html"]]],
  ["", [["access", "Access", "patina", "", [["access-entity", "Entity", "38", "brass"], ["access-local", "Local accounts", "124", "patina"], ["access-kyc", "KYC", "17", "copper"]]]]],
  ["", [["records", "Records", "brass", "", [["activity", "Activity log", "", "brass"], ["shared", "Shared", "6", "brass"], ["data", "Import / export", "", "brass"], ["compliance", "Compliance", "", "brass"]], "activity.html"]]],
  ["", [["other", "Other", "patina", "", [["2fa", "Two-factor", "", "patina"], ["wallet", "Wallet hub", "26", "moss"], ["backup", "Backup codes", "", "patina"], ["emergency", "Emergency access", "", "patina"]], "2fa.html"]]],
  ["", [["settings", "Settings", "slate", "", [["security", "Security", "", "patina"], ["devkeys", "Developer keys", "4", "slate"]], "security.html"]]],
];
const COL = { brass: "var(--brass)", patina: "var(--patina)", copper: "var(--copper)", slate: "var(--slate)", moss: "var(--moss)", rose: "var(--rose)" };
const esc = (s) => String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;");
const I = (d) => `<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${d}</svg>`;
const ic = { search: I('<circle cx="11" cy="11" r="7"/><path d="M21 21l-4-4"/>'), plus: I('<path d="M12 5v14M5 12h14"/>'), dl: I('<path d="M12 4v11M7 11l5 5 5-5M5 20h14"/>'), lock: I('<rect x="5" y="11" width="14" height="9" rx="2"/><path d="M8 11V8a4 4 0 018 0v3"/>'), filt: I('<path d="M4 6h16M7 12h10M10 18h4"/>') };

function shell({ id, theme, crumbs, body }) {
  const nav = NAV.map(([g, items]) => (g ? `<h6>${g}</h6>` : "") + items.map(([k, l, c, n, kids, href]) => { const open = !!kids; return `<a href="${href || k + ".html"}" class="${k === id ? "on" : ""}" style="--c:${COL[c]}"><span class="d"></span>${l}${kids ? `<em class="chev">${open ? "⌄" : "›"}</em>` : n ? `<em>${n}</em>` : ""}</a>` + (open ? `<div class="subnav">${kids.map(([kk, kl, kn, kc]) => `<a href="${kk}.html" class="${kk === id ? "on" : ""}" style="--c:${COL[kc || c]}">${kl}<em>${kn || ""}</em></a>`).join("")}</div>` : ""); }).join("")).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(crumbs.at(-1))} · Sylo</title><link rel="stylesheet" href="sylo.css"></head><body class="t-${theme}">
<aside class="rail"><div class="brand"><i></i><b>SYLO</b></div><div class="ws"><div>Northgate Holdings<small>WORKSPACE · 4 MEMBERS</small></div><span class="mono" style="color:var(--di)">⌄</span></div><nav class="nav">${nav}</nav><div class="lock"><p>Vault unlocked</p><small>Auto-lock in 12:40</small></div></aside>
<div class="main"><div class="top"><div class="crumb">${crumbs.map((c, i) => (i === crumbs.length - 1 ? `<b>${esc(c)}</b>` : `<span>${esc(c)}</span><span>/</span>`)).join("")}</div><div class="search">${ic.search}Search vault<kbd>⌘K</kbd></div><div class="av">MR</div></div><div class="page">${body}</div></div><nav class="mbar">${[["console", "Home"], ["entity", "Accounts"], ["access", "Access"], ["activity", "Records"], ["settings", "Settings"]].map(([k, l]) => `<a href="${k}.html" class="${id === k || id.startsWith(k + "-") ? "on" : ""}">${l}</a>`).join("")}</nav><script>document.addEventListener("click",function(e){var t=e.target.closest("[data-href]");if(t&&!e.target.closest("a,button"))location.href=t.dataset.href})</script></body></html>`;
}
const back = (label, href) => `<a class="back" href="${href}">‹ ${label}</a>`;
const lnk = (html, from, to) => html.split(from).join(to);
const head = (eb, h, p, acts = "") => `<div class="ph"><div><div class="eb">${eb}</div><h1>${h}</h1>${p ? `<p>${p}</p>` : ""}</div><div class="acts">${acts}</div></div>`;
const btn = (t, c = "") => `<a class="btn ${c}">${t}</a>`;
const tabs = (items) => `<div class="tabs">${items.map(([t, on, n]) => `<a class="${on ? "on" : ""}">${t}${n ? `<em>${n}</em>` : ""}</a>`).join("")}</div>`;
const kpis = (a) => `<div class="kpis">${a.map(([l, v, s, c]) => `<div class="kpi" ${c ? `style="--c:${COL[c]}"` : ""}><label>${l}</label><strong>${v}</strong><small>${s}</small></div>`).join("")}</div>`;
const card = (t, r, inner, pad = true) => `<section class="card"><header><h3>${t}</h3><span>${r || ""}</span></header>${pad ? `<div class="body">${inner}</div>` : inner}</section>`;
const pill = (t, k = "") => `<span class="pill ${k}">${t}</span>`;
const mk = (s) => `<span class="mk">${s}</span>`;
const bar = (p) => `<div class="bar"><i style="width:${p}%"></i></div>`;

function area(pts, w, h, color, labels) {
  const mx = Math.max(...pts) * 1.12, mn = Math.min(...pts) * 0.82, X = (i) => (i / (pts.length - 1)) * (w - 56) + 46, Y = (v) => h - 26 - ((v - mn) / (mx - mn)) * (h - 44);
  const d = pts.map((v, i) => `${i ? "L" : "M"}${X(i).toFixed(1)},${Y(v).toFixed(1)}`).join("");
  let g = ""; for (let k = 0; k < 4; k++) { const y = 10 + k * ((h - 36) / 3); g += `<line x1="46" x2="${w - 10}" y1="${y}" y2="${y}" stroke="var(--line)"/><text x="40" y="${y + 3}" text-anchor="end" font-size="10" fill="var(--di)">${Math.round((mx - (k * (mx - mn)) / 3) / 1000)}k</text>`; }
  const xl = labels.map((l, i) => `<text x="${X(Math.round((i * (pts.length - 1)) / (labels.length - 1)))}" y="${h - 6}" text-anchor="middle" font-size="10" fill="var(--di)">${l}</text>`).join("");
  return `<svg viewBox="0 0 ${w} ${h}" width="100%" style="display:block">${g}<path d="${d}L${X(pts.length - 1)},${h - 26}L${X(0)},${h - 26}Z" fill="${color}" opacity=".10"/><path d="${d}" fill="none" stroke="${color}" stroke-width="1.8"/><circle cx="${X(pts.length - 1)}" cy="${Y(pts.at(-1))}" r="3.5" fill="${color}"/>${xl}</svg>`;
}
function bars(vals, w, h, color) { const m = Math.max(...vals), bw = (w - 20) / vals.length; return `<svg viewBox="0 0 ${w} ${h}" width="100%" style="display:block">${vals.map((v, i) => { const bh = (v / m) * (h - 26); return `<rect x="${10 + i * bw + 3}" y="${h - 18 - bh}" width="${bw - 6}" height="${bh}" rx="2" fill="${color}" opacity="${i === vals.length - 1 ? 1 : 0.55}"/>`; }).join("")}</svg>`; }
const series = (n, a, s) => { let v = a, o = []; for (let i = 0; i < n; i++) { v += Math.sin(i * 0.7) * s + (i % 5) * s * 0.18 + s * 0.35; o.push(v); } return o; };
function donut(parts, size = 148) { const r = 54, c = 2 * Math.PI * r, tot = parts.reduce((a, p) => a + p[1], 0); let off = 0; return `<svg width="${size}" height="${size}" viewBox="0 0 148 148">${parts.map(([l, v, col]) => { const len = (v / tot) * c; const e = `<circle cx="74" cy="74" r="${r}" fill="none" stroke="${col}" stroke-width="16" stroke-dasharray="${len - 2} ${c - len + 2}" stroke-dashoffset="${-off}" transform="rotate(-90 74 74)"/>`; off += len; return e; }).join("")}</svg>`; }

const P = {};
/* 1 Console */
P.console = () => shell({ id: "console", theme: "brass", crumbs: ["Sylo", "Console"], body:
  head("Overview", "Good evening, Mira", "Everything under Northgate Holdings, current as of 22:41. Three items need a decision.", btn(ic.plus + " New entity", "p") + btn("Export snapshot")) +
  kpis([["Combined worth", "$482,310", "<span class=up>▲ 3.2%</span> · 30 days", "brass"], ["Entities", "38", "9 projects · 212 identities", "brass"], ["Local accounts", "124", "$61,480 held", "patina"], ["KYC entries", "17", "11 paid · 6 pending", "copper"]]) +
  `<div class="grid g-8-4 mb">${card("Worth over time", "12 months", area(series(24, 300000, 9000), 760, 250, "var(--brass)", ["Dec", "Mar", "Jun", "Sep", "Nov"]))}${card("Needs a decision", "3 open", `<div class="row"><div class="g"><b>2 recovery emails unverified</b><span>Entity · Aurelia Labs</span></div>${pill("warn", "warn").replace("warn</span>", "Review</span>")}</div><div class="row"><div class="g"><b>KYC renewal due in 6 days</b><span>KYC · Northgate Ltd</span></div>${pill("Due", "bad")}</div><div class="row"><div class="g"><b>Backup codes last rotated 94 days ago</b><span>Security</span></div>${pill("Stale", "warn")}</div>`, false)}</div>` +
  `<div class="grid g-7-5">${card("Recent activity", "Last 24 hours", `<div class="tl">${[["22:18", "Entity “Aurelia Labs” opened", "mira · Berlin", "brass"], ["19:02", "Wallet seed exported (encrypted)", "mira · same device", "moss"], ["16:40", "Shared “Ops KYC” with j.ortega", "read-only · 7 days", "copper"], ["11:12", "New sign-in from Lisbon", "passkey · new location", "patina"]].map((e) => `<div class="ev" style="--c:${COL[e[3]]}"><time>${e[0]}</time><i></i><div><b style="font-weight:500">${e[1]}</b><div class="mono" style="color:var(--di);font-size:11.5px">${e[2]}</div></div></div>`).join("")}</div>`, false)}${card("Holdings by account type", "USD", `<div style="display:flex;gap:24px;align-items:center">${donut([["Entity", 61, "var(--brass)"], ["Local", 24, "var(--patina)"], ["KYC", 15, "var(--copper)"]])}<div style="flex:1">${[["Entity", "$294,210", "var(--brass)"], ["Local", "$61,480", "var(--patina)"], ["KYC", "$126,620", "var(--copper)"]].map((x) => `<div class="row" style="padding:9px 0"><span style="width:8px;height:8px;border-radius:2px;background:${x[2]}"></span><div class="g"><b>${x[0]}</b></div><span class="num">${x[1]}</span></div>`).join("")}</div></div>`)}</div>` });

